SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·后唐纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e38f4580/content/books/zizhi-tongjian/vol-276/year-0927/part-01/sources/library/tongjian-276-july-opening/source.txt", "note": "《资治通鉴》后唐纪五，段落 zizhi-tongjian-a63549944a71-p003280；电子底本待考，分段待核", "id": "080f6be3-4284-592e-9dba-81060086496f"}, {"title": "资治通鉴·后唐纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0d4d8bd/content/books/zizhi-tongjian/vol-275/year-0926/part-08/sources/library/tongjian-275-926-yearend-and-927-opening/source.txt", "note": "《资治通鉴》后唐纪四，段落 zizhi-tongjian-a63549944a71-p003276；电子底本待考，分段待核", "id": "6472f1b8-836f-50a6-a937-57dadee225cc"}, {"title": "资治通鉴·后唐纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/69768554/content/books/zizhi-tongjian/vol-275/year-0927/part-04/sources/library/tongjian-275-chengdu-and-jingnan/source.txt", "note": "《资治通鉴》后唐纪四，段落 zizhi-tongjian-a63549944a71-p003279；电子底本待考，分段待核", "id": "abbb4d37-2394-54a7-bdd2-1ce0d8b99f93"}, {"title": "新五代史·卷六十四", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0d4d8bd/content/books/zizhi-tongjian/vol-275/year-0926/part-08/sources/library/xinwudaishi-064-926-monitor/source.txt", "note": "《新五代史》卷六十四，段落 xin-wudaishi-b08f244b9241-p003223；EPUB电子本，纸本及异文待核", "id": "ace164dc-65e1-5b5a-83b0-5c11180bd6b5"}, {"title": "新五代史·卷三十三", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/fa886303/content/books/zizhi-tongjian/vol-276/year-0927/part-03/sources/library/xinwudaishi-033-sunsheng-flight/source.txt", "note": "《新五代史》卷三十三，段落 xin-wudaishi-b08f244b9241-p001208；EPUB电子本，纸本及异文待核", "id": "b960e080-bde2-5e26-80f7-ddffe66f46f4"}, {"title": "旧五代史·卷九十七", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/fa886303/content/books/zizhi-tongjian/vol-276/year-0927/part-03/sources/library/jiuwudaishi-097-fanyanguang-march/source.txt", "note": "《旧五代史》卷九十七，段落 jiu-wudaishi-205deb4a7860-p002365；EPUB电子本，纸本及异文待核", "id": "be0ca5d2-119f-51a0-b84d-489dc17a6ac4"}, {"title": "资治通鉴·后唐纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6ee141a6/content/books/zizhi-tongjian/vol-275/year-0927/part-02/sources/library/tongjian-275-927-offices-and-khitan/source.txt", "note": "《资治通鉴》后唐纪四，段落 zizhi-tongjian-a63549944a71-p003277；电子底本待考，分段待核", "id": "48aeaaad-2a12-5e70-8713-f62f828c06f3"}, {"title": "《旧五代史·崔协传世系》", "author": "薛居正等", "source_type": "primary", "edition": "从选定的EPUB全文TXT逐字导出；电子版本，纸本及异文尚待全面校核。", "url": "https://github.com/greed-216/histree/blob/1ea48b6b9b16894d8d7366a8b52047d83b046e24/content/revisions/2026-10-12-review-927/relationship-supplement/sources/library/jiuwudaishi-058-cuixie-ancestry/source.txt", "note": "《旧五代史》卷五十八，段落 jiu-wudaishi-205deb4a7860-p001541；EPUB电子本，纸本及异文待核", "id": "81f54a30-37c7-5d11-99f0-991a2a502a18"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "姚彦章", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "姚彦章是楚国官员，927年马殷建国设置官属时任左丞相。", "biography": null, "status": "draft", "id": "3efed9a0-6cef-5447-bb54-71b79c98d5d0"}, {"name": "马殷", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "马殷是楚国君主，907年获后梁封为楚王。《资治通鉴》记931年十二月葬于衡阳；《新五代史》作上潢，地点差异分别保留。", "biography": null, "status": "draft", "id": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"name": "李铎", "aliases": ["李鐸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李铎是楚国官员，927年马殷建国设置官属时任司徒。", "biography": null, "status": "draft", "id": "07f48c6d-70df-5c54-94aa-b393820eb4f3"}, {"name": "崔颖", "aliases": ["崔穎"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "崔颖是楚国官员，927年马殷建国设置官属时任司空。", "biography": null, "status": "draft", "id": "23247ff1-f4f1-59e7-9cde-eabb674598ce"}, {"name": "拓跋恒", "aliases": ["元恒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "拓跋恒是楚国官员，927年任仆射。《资治通鉴》说他原姓元、避马殷父名讯改姓；《新五代史》人名及马父名不同，分别保留。", "biography": null, "status": "draft", "id": "a53a8f9a-f7db-5e25-b74c-4b81973658e7"}, {"name": "张彦瑶", "aliases": ["張彥瑤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "张彦瑶是楚国官员，927年与张迎一起主管机要司。", "biography": null, "status": "draft", "id": "28a0188b-bb80-5021-b300-5826c891faa6"}, {"name": "张迎", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "张迎是楚国官员，927年与张彦瑶一起主管机要司。", "biography": null, "status": "draft", "id": "32978d7c-4f10-5cde-84f0-34dc91caa32d"}, {"name": "丁知俊", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "丁知俊曾任左厢马步都虞候，曾与李严一同出使前蜀。927年受孟知祥命令为李严埋葬遗体。", "biography": null, "status": "draft", "id": "a0fa1a87-9785-5ad0-8465-9eada84c8e4c"}, {"name": "孟知祥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "孟知祥是后蜀君主。925年，后唐任命他为西川节度使、同平章事。", "biography": null, "status": "draft", "id": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"name": "武漳", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武漳是文水人，曾任孟知祥牙内指挥使。受命到晋阳迎接孟知祥家属入蜀。", "biography": null, "status": "draft", "id": "512958a6-c62a-503b-8d14-86c8a5de96d5"}, {"name": "赵季良", "aliases": ["趙季良"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵季良是后蜀官员。934年二月，获任司空兼门下侍郎、同平章事，仍兼领武泰节度使；同年受孟知祥临终托付，辅佐继位者。", "biography": null, "status": "draft", "id": "5cccbc59-1a95-5072-a1b8-d769fd075712"}, {"name": "李昊", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李昊曾为孟知祥起草奏表。932年劝孟知祥亲自向后唐请求王爵和任官权限，避免权柄落在诸将手中。", "biography": null, "status": "draft", "id": "ecf7855b-2568-576c-b0b9-58e6b1f120fa"}, {"name": "李敬周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李敬周曾任西川节度副使、内外马步军都指挥使。927年孟知祥先任他为遂州留后，随后朝廷另行授任武信留后。", "biography": null, "status": "draft", "id": "9d3acb1e-1a61-5c88-8c7c-74c351cee906"}, {"name": "王彦铢", "aliases": ["王彥銖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王彦铢曾任客将，奉孟知祥示意扣押李严，将其带下斩杀；后来任都押牙。932年李昊拒绝暂管梓州军府后，孟知祥任他为东川监押。", "biography": null, "status": "draft", "id": "8fe89798-6ba7-5df8-bd44-a5cd5847aa62"}, {"name": "孙晟", "aliases": ["孫晟", "孙凤", "孫鳳", "孙忌", "孫忌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "孙晟曾任判官。932年徐知诰设礼贤院邀请士大夫，孙晟与海陵陈觉参与时事谈议。", "biography": null, "status": "draft", "id": "38c30b43-89f4-5133-8970-38f2fb8f157e"}, {"name": "朱守殷", "aliases": ["硃守殷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朱守殷曾任宣武节度使。927年据汴州抗拒朝廷，城陷前杀死族人，再命身边人将自己斩杀。", "biography": null, "status": "draft", "id": "904d09d9-a2de-5358-befd-69a3fa7699a6"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "李昪幼年被杨行密军士掳走，先由杨行密收养，后交给徐温收养，取名徐知诰。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "范延光", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》同光元年条记载，范延光受李嗣源派遣，送交康延孝的蜡封书信，并向李存勖提出建议。", "biography": null, "status": "draft", "id": "6889e460-4b23-5243-9441-b5c3a78da98f"}, {"name": "李嗣源", "aliases": ["李亶", "后唐明宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "biography": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "status": "draft", "id": "5d1886ff-b3ec-56f6-a154-b5633c294037"}, {"name": "韩珙", "aliases": ["韓珙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "韩珙曾为魏王李继岌押牙，受命押送蜀地珍货金帛，经过峡口时被高季兴杀死。", "biography": null, "status": "draft", "id": "89447606-a592-5a18-9657-3658441b285c"}, {"name": "李继岌", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "李继岌曾率后唐军平定前蜀，受封魏王，派韩珙等押运蜀地财物。此事属于927年记事中的追叙。", "biography": null, "status": "draft", "id": "d160654e-338c-57b1-9759-208ae0af8250"}, {"name": "崔邠", "aliases": [], "birth_year": null, "death_year": null, "description": "《旧五代史》崔协传记崔邠为太常卿，是崔协的曾祖父，生卒年月未详。", "era": null, "status": "draft", "id": "863e2d44-2753-5ae7-a62b-cb838d6892b1"}, {"name": "崔协", "aliases": ["崔協"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "崔协任后唐门下侍郎、同平章事。929年二月在须水去世，获追赠尚书仆射；《旧五代史》本纪作右仆射，列传作左仆射。", "biography": null, "status": "draft", "id": "56693be3-8983-515d-b1ca-96e270e13442"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person_relationship (id, person_a, person_b, relation_type, description, status)
SELECT id, person_a, person_b, relation_type, description, status FROM jsonb_populate_recordset(NULL::public.person_relationship, '[{"relation_type": "左丞相", "description": "姚彦章在马殷统治的楚国任左丞相，见927年设置官属的记载。具体始任、离任年月未详。", "status": "draft", "id": "84cf699f-cbf0-5d8d-9623-bcab3deac1d5", "person_a": "3efed9a0-6cef-5447-bb54-71b79c98d5d0", "person_b": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"relation_type": "司徒", "description": "李铎在马殷统治的楚国任司徒，见927年设置官属的记载。具体始任、离任年月未详。", "status": "draft", "id": "cfbb0e4c-9158-5590-a557-25eef9572b65", "person_a": "07f48c6d-70df-5c54-94aa-b393820eb4f3", "person_b": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"relation_type": "司空", "description": "崔颖在马殷统治的楚国任司空，见927年设置官属的记载。具体始任、离任年月未详。", "status": "draft", "id": "80aab96b-14a5-5712-a18b-a00384052f5a", "person_a": "23247ff1-f4f1-59e7-9cde-eabb674598ce", "person_b": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"relation_type": "仆射", "description": "拓跋恒在马殷统治的楚国任仆射，见927年设置官属的记载。《新五代史》写拓拔常，姓名异文保留。", "status": "draft", "id": "35b84f66-089c-53a9-927f-082cc20f1120", "person_a": "a53a8f9a-f7db-5e25-b74c-4b81973658e7", "person_b": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"relation_type": "机要官", "description": "张彦瑶在马殷统治的楚国主管机要司，927年与张迎同时见于记载。具体始任、离任年月未详。", "status": "draft", "id": "829b2b5c-e2c6-556d-b24b-68709b8b9c6a", "person_a": "28a0188b-bb80-5021-b300-5826c891faa6", "person_b": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"relation_type": "机要官", "description": "张迎在马殷统治的楚国主管机要司，927年与张彦瑶同时见于记载。具体始任、离任年月未详。", "status": "draft", "id": "c9ae2244-74bc-5833-9862-c327e2a915eb", "person_a": "32978d7c-4f10-5cde-84f0-34dc91caa32d", "person_b": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"relation_type": "部将", "description": "丁知俊为孟知祥部下的左厢马步都虞候，927年受命埋葬李严遗体。记录所述任职，不据“故人”推亲缘。", "status": "draft", "id": "7020ac6e-15ef-5217-9abf-c8a6ee662c97", "person_a": "a0fa1a87-9785-5ad0-8465-9eada84c8e4c", "person_b": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"relation_type": "牙内指挥使", "description": "武漳是孟知祥的牙内指挥使，曾受命迎接孟知祥家属入蜀。实际派遣日及任职起止未载。", "status": "draft", "id": "07ced3d6-1992-553e-8667-1ed887bc0c74", "person_a": "512958a6-c62a-503b-8d14-86c8a5de96d5", "person_b": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"relation_type": "节度副使", "description": "赵季良获任孟知祥所镇西川的节度副使。“有旧”只说明此前交往，不据此补亲缘或师徒。", "status": "draft", "id": "1c95ef81-1e43-5dcc-ac50-03575fb61355", "person_a": "5cccbc59-1a95-5072-a1b8-d769fd075712", "person_b": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"relation_type": "观察推官", "description": "李昊返回蜀地后，孟知祥任他为观察推官。原文未单列具体任职日期。", "status": "draft", "id": "ff03377f-6564-5c56-9501-be2952446ff9", "person_a": "ecf7855b-2568-576c-b0b9-58e6b1f120fa", "person_b": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"relation_type": "节度副使", "description": "李敬周此前任孟知祥所镇西川的节度副使、内外马步军都指挥使，927年被孟知祥先任遂州留后。任职关系不延长到以后所有时期。", "status": "draft", "id": "4e8e19f6-e26f-5844-879a-43bc1f0540d5", "person_a": "9d3acb1e-1a61-5c88-8c7c-74c351cee906", "person_b": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"relation_type": "客将", "description": "《新五代史》记王彦铢为孟知祥客将，奉示意押下李严斩杀。具体始任、离任日期未载。", "status": "draft", "id": "9430e4f0-583d-52fc-a881-809c894b3ca9", "person_a": "8fe89798-6ba7-5df8-bd44-a5cd5847aa62", "person_b": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"relation_type": "判官", "description": "孙晟曾被朱守殷任为判官。《新五代史》明示任职，未据参与一次叛乱推永久盟友。", "status": "draft", "id": "34867fe4-1f8f-502e-82f6-f17d2016ee02", "person_a": "38c30b43-89f4-5133-8970-38f2fb8f157e", "person_b": "904d09d9-a2de-5358-befd-69a3fa7699a6"}, {"relation_type": "宾客", "description": "孙晟逃往吴国后，徐知诰将他留为宾客。徐知诰沿李昪同人身份，不将宾客当作已任宰相。", "status": "draft", "id": "19acb2a7-7097-5378-9552-b02ab69a5d94", "person_a": "38c30b43-89f4-5133-8970-38f2fb8f157e", "person_b": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"relation_type": "亲校", "description": "范延光曾在李嗣源主政相州时被收为亲校。此为《旧五代史》的此前经历，具体年份未载，不定为927年始任。", "status": "draft", "id": "94f8a9ed-7ad6-5e43-9316-a80cc20fde96", "person_a": "6889e460-4b23-5243-9441-b5c3a78da98f", "person_b": "5d1886ff-b3ec-56f6-a154-b5633c294037"}, {"relation_type": "押牙", "description": "韩珙是魏王李继岌的押牙，曾受命押送蜀地财物。此为927年记事中的追叙，不定为李继岌死后发令。", "status": "draft", "id": "91bdd728-8f8f-5166-a6fe-6e0be04ae9bc", "person_a": "89447606-a592-5a18-9657-3658441b285c", "person_b": "d160654e-338c-57b1-9759-208ae0af8250"}, {"relation_type": "曾祖父", "description": "崔邠是崔协的曾祖父。《资治通鉴》称崔协为邠之曾孙，《旧五代史》崔协传也列曾祖邠为太常卿。生卒年月未详。", "status": "draft", "id": "6e81dedb-574f-56fb-86ca-2a873ae548a1", "person_a": "863e2d44-2753-5ae7-a62b-cb838d6892b1", "person_b": "56693be3-8983-515d-b1ca-96e270e13442"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

